import{_ as t,o as a,c as e,a2 as s}from"./chunks/framework.XXezeKOl.js";const c=JSON.parse('{"title":"为什么需要多 Agent","description":"多 Agent 不是默认选项：先把单 Agent 做好，只在可并行、需要上下文隔离或强专业分工时才拆分。","frontmatter":{"title":"为什么需要多 Agent","description":"多 Agent 不是默认选项：先把单 Agent 做好，只在可并行、需要上下文隔离或强专业分工时才拆分。"},"headers":[],"relativePath":"guide/12-multi-agent/why-multi-agent.md","filePath":"guide/12-multi-agent/why-multi-agent.md","lastUpdated":null}'),l={name:"guide/12-multi-agent/why-multi-agent.md"};function i(r,n,o,p,g,u){return a(),e("div",null,[...n[0]||(n[0]=[s(`<h1 id="为什么需要多-agent" tabindex="-1">为什么需要多 Agent <a class="header-anchor" href="#为什么需要多-agent" aria-label="Permalink to &quot;为什么需要多 Agent&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>说清楚&quot;多 Agent 系统&quot;到底指什么，以及它和&quot;一个 Agent 调很多工具&quot;的区别</li><li>理解为什么大多数场景下单 Agent 更好：更便宜、更好调试、上下文不丢失</li><li>掌握多 Agent 真正划算的三类场景：可并行的研究、上下文隔离、专业分工</li><li>学会用一张检查清单判断&quot;我该不该拆&quot;</li></ul></div><h2 id="先统一概念" tabindex="-1">先统一概念 <a class="header-anchor" href="#先统一概念" aria-label="Permalink to &quot;先统一概念&quot;">​</a></h2><p>本站说的 <strong>多 Agent 系统（Multi-Agent System）</strong>，指的是由多个各自拥有独立上下文、独立系统提示词、通常也有独立工具集的 LLM 循环协作完成一个任务。每个 Agent 都是一个完整的 <a href="/guide/06-agent-loop/react">Agent 循环</a>：思考 → 调用工具 → 观察 → 再思考。</p><p>它和下面两种东西不同：</p><table tabindex="0"><thead><tr><th>形态</th><th>上下文</th><th>典型例子</th></tr></thead><tbody><tr><td>单 Agent + 多工具</td><td>一份上下文，模型自己决定调哪个工具</td><td>一个客服 Agent 能查订单、查物流、退款</td></tr><tr><td>Workflow（固定流程）</td><td>每一步可能调 LLM，但流程由代码写死</td><td>&quot;翻译 → 校对 → 排版&quot;三步管道</td></tr><tr><td>多 Agent</td><td>多份互相隔离的上下文，Agent 之间传递消息或结果</td><td>主 Agent 派 5 个子 Agent 并行调研 5 个方向</td></tr></tbody></table><p>关键区别在于 <strong>上下文是否隔离</strong>。单 Agent 里，所有工具结果都堆进同一个消息列表；多 Agent 里，子 Agent 读了 50 个网页，只把 500 字的结论交回去，主 Agent 永远看不到那 50 个网页的原文。这既是多 Agent 最大的优点，也是它最大的风险来源。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单 Agent：                         多 Agent（主从）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────────┐           ┌──────────────┐</span></span>
<span class="line"><span>│ 一个上下文窗口        │           │ 主 Agent      │  只看到各子任务的摘要</span></span>
<span class="line"><span>│  system prompt       │           └──┬────┬────┬─┘</span></span>
<span class="line"><span>│  user 任务            │              │    │    │   派发子任务</span></span>
<span class="line"><span>│  tool 结果 1          │           ┌──▼┐ ┌─▼─┐ ┌▼──┐</span></span>
<span class="line"><span>│  tool 结果 2          │           │子A│ │子B│ │子C│  各自独立上下文</span></span>
<span class="line"><span>│  ...越来越长          │           └───┘ └───┘ └───┘  各自读大量资料</span></span>
<span class="line"><span>└──────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="大多数情况下-单-agent-更好" tabindex="-1">大多数情况下，单 Agent 更好 <a class="header-anchor" href="#大多数情况下-单-agent-更好" aria-label="Permalink to &quot;大多数情况下，单 Agent 更好&quot;">​</a></h2><p>这一点值得先说清楚：<strong>绝大多数业务场景，一个设计良好的单 Agent 就够了，而且更好。</strong> 理由很具体：</p><ol><li><strong>信息不丢失。</strong> 单 Agent 的每一次决策都基于完整历史。多 Agent 之间只传摘要，摘要必然有损。子 Agent A 发现的一个关键约束，如果没写进它交回的结论，子 Agent B 就不知道，最后两个人的产出互相矛盾。</li><li><strong>成本更低。</strong> 每个 Agent 都要重复读系统提示词、任务描述和共享背景。多 Agent 系统的 Token 消耗常常是单 Agent 的数倍，这是公开工程经验里反复出现的结论。</li><li><strong>更好调试。</strong> 单 Agent 出错，你看一条轨迹就能定位。多 Agent 出错，你要在多条并发轨迹之间对时间线，判断是&quot;主 Agent 拆错了任务&quot;还是&quot;子 Agent 执行错了&quot;还是&quot;汇总时丢了信息&quot;。</li><li><strong>决策一致。</strong> 写代码、改文档这类任务，前后决策高度耦合。拆给两个 Agent 分别写前端和后端，接口约定很容易对不上。</li></ol><p>很多人想拆多 Agent，其实真正的问题是别的：</p><table tabindex="0"><thead><tr><th>你以为的问题</th><th>真正的原因</th><th>更好的解法</th></tr></thead><tbody><tr><td>&quot;一个 Agent 管不了这么多工具&quot;</td><td>工具描述写得差、工具太多太像</td><td><a href="/guide/05-tool-calling/tool-design">工具设计原则</a>，合并或分组工具</td></tr><tr><td>&quot;上下文太长，模型变笨&quot;</td><td>工具结果原样塞回上下文</td><td><a href="/guide/07-context-engineering/window-management">上下文窗口管理</a>、<a href="/guide/07-context-engineering/compression">压缩与摘要</a></td></tr><tr><td>&quot;需要多个角色把关&quot;</td><td>缺少检查步骤</td><td>加一步 <a href="/guide/06-agent-loop/reflection">Reflection</a> 或固定的校验 Workflow</td></tr><tr><td>&quot;流程很长，容易跑偏&quot;</td><td>缺少计划</td><td><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></td></tr></tbody></table><p>先试这些，再考虑拆分。</p><h2 id="多-agent-真正划算的三类场景" tabindex="-1">多 Agent 真正划算的三类场景 <a class="header-anchor" href="#多-agent-真正划算的三类场景" aria-label="Permalink to &quot;多 Agent 真正划算的三类场景&quot;">​</a></h2><h3 id="_1-可并行的广度型研究" tabindex="-1">1. 可并行的广度型研究 <a class="header-anchor" href="#_1-可并行的广度型研究" aria-label="Permalink to &quot;1. 可并行的广度型研究&quot;">​</a></h3><p>典型任务：&quot;调研 2020 年以来所有主流开源向量数据库，对比它们的索引类型、分布式能力和许可证。&quot;</p><p>这类任务的特点是 <strong>子任务之间几乎独立</strong>：调研 Milvus 不需要知道 Qdrant 的结论。拆成多个子 Agent 并行跑，有两个收益：</p><ul><li><strong>墙钟时间缩短</strong>：5 个方向并行，总耗时接近最慢的那一个，而不是 5 个相加。</li><li><strong>总探索量变大</strong>：每个子 Agent 都有一整个上下文窗口可以用来读资料，系统整体能&quot;读&quot;的信息量是单 Agent 的数倍。</li></ul><p>Anthropic 公开分享过他们的多 Agent 研究系统，结论正是：在广度优先、可并行的研究类问题上，多 Agent 明显好于单 Agent，代价是 Token 消耗大幅上升。所以它适合 <strong>任务价值高到能覆盖额外成本</strong> 的场景。</p><h3 id="_2-上下文隔离" tabindex="-1">2. 上下文隔离 <a class="header-anchor" href="#_2-上下文隔离" aria-label="Permalink to &quot;2. 上下文隔离&quot;">​</a></h3><p>有些子任务会产生大量&quot;中间垃圾&quot;：搜索结果、网页原文、日志、测试输出。主任务只需要结论。</p><p>例如一个代码 Agent 需要&quot;在整个仓库里找出所有调用了已废弃 API 的地方&quot;。如果主 Agent 自己做，几十次搜索结果会把上下文塞满，后面真正改代码时反而记不住需求。交给一个子 Agent 去搜，只返回一个文件和行号列表，主 Agent 的上下文就保持干净。</p><p>Claude Code 等编码工具里的&quot;子 Agent&quot;（subagent）主要就是这个用途：<strong>用一次性的上下文去做脏活，只把结论带回来。</strong></p><h3 id="_3-专业分工与权限隔离" tabindex="-1">3. 专业分工与权限隔离 <a class="header-anchor" href="#_3-专业分工与权限隔离" aria-label="Permalink to &quot;3. 专业分工与权限隔离&quot;">​</a></h3><p>当不同子任务需要 <strong>完全不同的系统提示词、工具集或权限</strong> 时，拆开更清晰也更安全：</p><ul><li>一个&quot;数据库 Agent&quot;只有只读 SQL 工具，一个&quot;邮件 Agent&quot;只有发送草稿的工具，互相不能越权。</li><li>一个审查 Agent 不看实现者的推理过程，只看最终代码，审查更独立（类似人类的 code review 不该被作者的思路带偏）。</li><li>不同 Agent 可以用不同的模型：便宜的小模型做检索和分类，强模型做规划和汇总。</li></ul><h2 id="一张决策清单" tabindex="-1">一张决策清单 <a class="header-anchor" href="#一张决策清单" aria-label="Permalink to &quot;一张决策清单&quot;">​</a></h2><p>在动手拆分之前，逐条回答：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ] 单 Agent + 好的工具设计 + 上下文管理，我已经认真试过了吗？</span></span>
<span class="line"><span>[ ] 子任务之间真的独立吗？（需要频繁互相同步的任务不适合拆）</span></span>
<span class="line"><span>[ ] 子任务会产生大量主任务不需要的中间信息吗？</span></span>
<span class="line"><span>[ ] 不同子任务需要不同的权限、工具或模型吗？</span></span>
<span class="line"><span>[ ] 任务价值能覆盖数倍的 Token 成本吗？</span></span>
<span class="line"><span>[ ] 我有能力追踪多条并发轨迹吗？（见 [评估与可观测性] 模块）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>前两条有一条是&quot;否&quot;，就先别拆。后面四条至少满足一条，拆分才有意义。可观测性部分见 <a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a>。</p><h2 id="演进路径" tabindex="-1">演进路径 <a class="header-anchor" href="#演进路径" aria-label="Permalink to &quot;演进路径&quot;">​</a></h2><p>推荐的演进顺序是从简单到复杂，每一步都用 <a href="/guide/14-evaluation/eval-design">评估集</a> 证明收益后再往下走：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单次 LLM 调用</span></span>
<span class="line"><span>   └─▶ 固定 Workflow（代码编排几次调用）</span></span>
<span class="line"><span>         └─▶ 单 Agent（模型自主调用工具）</span></span>
<span class="line"><span>               └─▶ 单 Agent + 子 Agent（仅用于上下文隔离的脏活）</span></span>
<span class="line"><span>                     └─▶ 主从多 Agent（并行研究）</span></span>
<span class="line"><span>                           └─▶ 更复杂的拓扑（交接、辩论、网状）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>大部分生产系统停在第三或第四层。具体的编排方式见下一篇 <a href="/guide/12-multi-agent/patterns">编排模式：主从、流水线、交接、辩论</a>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>为了&quot;看起来高级&quot;而拆分。</strong> 给 Agent 起&quot;产品经理&quot;&quot;架构师&quot;&quot;程序员&quot;这样的角色名，并不会让它们更聪明，只会让信息在角色之间多传几手、多丢几次。</li><li><strong>拆分耦合的任务。</strong> 让两个 Agent 分别写同一个功能的前后端，最常见的结果是接口不一致。耦合紧的任务交给一个 Agent 按顺序做。</li><li><strong>没有基线。</strong> 不先测单 Agent 的效果，就无法证明多 Agent 带来了提升，只能确定成本上去了。</li><li><strong>忽视成本放大。</strong> 每多一个 Agent，系统提示词、共享背景都要重复计费。上线前先估算一次完整任务的 Token 消耗，见 <a href="/guide/12-multi-agent/pitfalls">多 Agent 的坑与成本控制</a>。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>多 Agent 与&quot;单 Agent 调用很多工具&quot;最本质的区别是什么？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>上下文是否隔离。多 Agent 中每个 Agent 拥有独立的上下文窗口，彼此只通过消息或结果摘要交流；单 Agent 所有信息都在同一个上下文里。隔离带来了并行和&quot;不被中间信息污染&quot;的好处，也带来了信息丢失和协调成本。</p></details><ol start="2"><li>下面哪个任务最适合多 Agent？A. 给一个 Python 函数加单元测试；B. 对比 8 家云厂商的 GPU 实例规格和地域覆盖；C. 把一篇中文文章翻译成英文。</li></ol><details class="details custom-block"><summary>查看答案</summary><p>B。8 家厂商的调研互相独立，可以并行，每个子任务都需要读大量网页，只需要回传结构化结论。A 和 C 是单一、连贯的任务，单 Agent 或简单 Workflow 即可。</p></details><ol start="3"><li>你的 Agent 有 40 个工具，模型经常选错工具。同事建议拆成 4 个专业 Agent，你会先做什么？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>先检查工具设计：是否有功能重叠、命名含糊、描述不清的工具，能否合并或按场景动态加载工具子集。工具选择错误通常是工具设计问题，拆分 Agent 会额外引入路由错误和信息丢失。如果优化后仍有明确的权限或领域边界，再考虑拆分。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Building effective agents（Anthropic）</a>：从 Workflow 到 Agent 的分层思路</li><li><a href="https://www.anthropic.com/engineering/multi-agent-research-system" target="_blank" rel="noreferrer">How we built our multi-agent research system（Anthropic）</a>：多 Agent 研究系统的工程经验与成本讨论</li><li><a href="https://cognition.ai/blog/dont-build-multi-agents" target="_blank" rel="noreferrer">Don&#39;t Build Multi-Agents（Cognition）</a>：反方观点，强调上下文共享的重要性</li><li>本站：<a href="/guide/10-mcp/a2a">A2A：Agent 之间的协议</a>、<a href="/projects/07-writing-team">项目 07：多 Agent 写作团队</a></li></ul>`,46)])])}const h=t(l,[["render",i]]);export{c as __pageData,h as default};
